interface Org {
  id?: string;
  [key: string]: unknown;
}

interface User {
  id?: string;
  orgId: string;
  org?: Org;
  [key: string]: unknown;
}

async function fetchJson<T>(url: string): Promise<T> {
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error(`Request failed with status ${res.status}: ${url}`);
  }
  return (await res.json()) as T;
}

export async function loadUser(id: string): Promise<User> {
  const user = await fetchJson<User>(`/api/users/${encodeURIComponent(id)}`);
  const org = await fetchJson<Org>(`/api/orgs/${encodeURIComponent(user.orgId)}`);
  return { ...user, org };
}

export async function loadUsers(ids: string[]): Promise<User[]> {
  return await Promise.all(ids.map((id) => loadUser(id)));
}

